//! The logistics fixture: a seed-fed project exercising the shapes the
//! sample project cannot — `var()`-controlled enabled/disabled nodes, raw
//! data that lives only in seeds, `ref()` inside hooks, analyses and an
//! `on-run-start` hook, a vendored local package (macros, a model, a
//! custom generic test), and project-local macros carrying the
//! `ref()`/`source()` calls (literal arguments, bound arguments, a nested
//! macro chain, and a project-qualified invoke — the shapes a real
//! `depends_on` must reproduce).
//!
//! `tests/fixtures/logistics_manifest.json` is generated by REAL dbt from
//! `tests/fixtures/logistics_project/` — regenerate with:
//!
//! ```sh
//! cargo xtask gen-fixture-manifest \
//!     --project tests/fixtures/logistics_project --dbt-version 1.12.6
//! ```
//!
//! `tests/fixtures/logistics_vars_manifest.json` pairs it under a fixed
//! `--vars` map (`common::LOGISTICS_VARS`, which flips every `enabled`
//! channel) — regenerate with the same command plus
//! `--vars "$(sed -n 's/.*LOGISTICS_VARS//' tests/common/mod.rs)"` spelled
//! as that literal:
//!
//! ```sh
//! cargo xtask gen-fixture-manifest \
//!     --project tests/fixtures/logistics_project --dbt-version 1.12.6 \
//!     --vars '{env: prod, enable_experimental: true, lane_pairs_enabled: true, fleet_flag: true, telematics_flag: "True", alerts_enabled: false, strict_event_check: true, probe_enabled: true}' \
//!     --out tests/fixtures/logistics_vars_manifest.json
//! ```
//!
//! Like the sample consistency suite this pins manifest↔source parity, plus
//! the shapes above. Fixture-specific documented differences (beyond the
//! shared ones in `common::consistency`):
//! - Compiled-only lint rules (`unused_cte`, `order_by_without_limit`) fire
//!   only in manifest mode: the `shipkit` macro's expansion exists solely
//!   in `compiled_code`, while source mode's raw text is a bare unresolved
//!   `{{ shipkit.audited_select(...) }}` call.
//! - The singular `.sql` test registers on `ops_run_log` in the manifest;
//!   source mode never synthesizes singular tests, so its `tests:N` badge
//!   differs — the lineage-render comparison skips the handful of nodes
//!   whose subgraph carries that badge.

mod common;
use common::consistency as cmp;
use common::{
    LOGISTICS_MANIFEST as MANIFEST, LOGISTICS_PROJECT as PROJECT, LOGISTICS_VARS as VARS,
    LOGISTICS_VARS_MANIFEST as VARS_MANIFEST,
};
use std::collections::{BTreeMap, BTreeSet};

/// Edges the source loader records but real dbt's manifest never does —
/// the `target.name == 'prod'` arm of each branch-split model (verified
/// against the generated manifests: dbt keeps the `dev`-rendered arm
/// only). Source mode can't evaluate `target.name`, so the unprovable
/// arm's calls edge conservatively. `stg_execute_feed`'s
/// `{% if execute %}` arm is no longer here — `execute` is parse-time
/// false, so that call is provably dead and edges nowhere, matching the
/// manifest. Lint sees the same calls as possible consumers without
/// adding them to the graph.
const SOURCE_ONLY_EDGES: &[(&str, &str)] = &[
    (
        "source.logistics.raw.prod_orders",
        "model.logistics.stg_order_feed",
    ),
    (
        "model.logistics.stg_prod_orders",
        "model.logistics.int_order_split",
    ),
    // The `{% if execute %}` arm's source call is no longer source-only:
    // provably-dead-arm calls edge nowhere, matching the manifest's empty
    // `depends_on` (the literal call still counts as a possible read for
    // the lint rules in both modes).
];

use dbtl::{
    build_model_list, layout, load_dag, run_rules, Dag, LintConfig, LintInput, PackageScope,
    SortMode, SqlDialect, SqlParseResolver,
};

/// (manifest-mode Dag, source-mode Dag) of the logistics project, manifest
/// side already scoped to the root project.
fn dags() -> (Dag, Dag) {
    cmp::dags(
        MANIFEST,
        PROJECT,
        "cargo xtask gen-fixture-manifest --project tests/fixtures/logistics_project",
    )
}

#[test]
fn node_sets_and_infos_are_identical() {
    let (m, s) = dags();
    cmp::assert_node_infos_identical(&m, &s, cmp::NO_DROPPED_EDGES, SOURCE_ONLY_EDGES);
}

#[test]
fn full_lineage_closures_are_identical() {
    let (m, s) = dags();
    cmp::assert_closures_identical(&m, &s, cmp::NO_DROPPED_EDGES, SOURCE_ONLY_EDGES);
}

#[test]
fn details_are_identical_modulo_profile_data() {
    let (m, s) = dags();
    cmp::assert_details_identical(&m, &s);
}

#[test]
fn tests_are_identical_as_kind_column_multisets() {
    // Covers generic schema tests (unique/not_null/relationships), the seed
    // column tests, and the package's custom `no_negative_amounts` generic —
    // all registered identically in both modes; the singular test rides the
    // shared manifest-side exclusion.
    let (m, s) = dags();
    cmp::assert_tests_identical(&m, &s);
}

#[test]
fn project_name_is_identical() {
    let (m, s) = dags();
    assert_eq!(m.project_name(), Some("logistics"), "manifest mode");
    assert_eq!(s.project_name(), Some("logistics"), "source mode");
}

#[test]
fn var_disabled_nodes_are_absent_in_both_modes() {
    // Every `var()`-driven disable channel parks the node under dbt's
    // `disabled` (never `nodes`), so both modes must drop them all:
    //   experimental/*       models: tree `+enabled: var('enable_experimental')` (unset → false)
    //   fct_lane_pairs       in-file `config(enabled=var('lane_pairs_enabled'))` — the
    //                        project-scoped vars.yml entry (false) shadows the top-level (true)
    //   fct_returns          in-file `config(enabled=var('track_returns', false))` (unset → default)
    //   assert_events_in_order  singular test, in-file `config(enabled=var('strict_event_check', false))`
    //   deep_audit_probe     analyses: tree `+enabled: var('probe_enabled', false)`
    let (m, s) = dags();
    for uid in [
        "model.logistics.exp_demand_forecast",
        "model.logistics.exp_empty_miles",
        "model.logistics.fct_lane_pairs",
        "model.logistics.fct_returns",
        "test.logistics.assert_events_in_order",
        "analysis.logistics.deep_audit_probe",
    ] {
        assert!(!m.contains(uid), "manifest mode keeps {uid}");
        assert!(!s.contains(uid), "source mode keeps {uid}");
    }
    // …and the nodes the same vars turn ON must be present in both modes:
    //   pilot/*              models: tree `+enabled: var('enable_pilot')` → vars.yml true
    //   fct_service_alerts   in-file `config(enabled=var('alerts_enabled'))` → vars.yml true
    for uid in [
        "model.logistics.pilot_dock_queue",
        "model.logistics.pilot_lane_estimates",
        "model.logistics.fct_service_alerts",
    ] {
        assert!(m.contains(uid), "manifest mode drops {uid}");
        assert!(s.contains(uid), "source mode drops {uid}");
    }
}

#[test]
fn enabled_expressions_evaluate_identically_in_both_modes() {
    // Every enabled-expression shape the shared evaluator must resolve —
    // pinned against a real dbt 1.12.6 parse of the same tree. The
    // node-set comparison above already covers them; this pin names the
    // shapes so a regression reports WHICH expression form broke.
    let (m, s) = dags();
    for uid in [
        // `==`/`!=` on vars, `in` over a literal list, `and` mixing a bare
        // var and a comparison, `|` as_bool on a string var, the
        // `and`/`not`/`or`/`==` chain on the sandbox tree `+enabled`, the
        // Jinja `is` tests (sameas/none), and the schema `config.enabled`
        // Jinja string whose file must keep its descriptions/tests
        // (asserted by tests/details parity).
        "model.logistics.fct_region_gate", // var('region') != 'emea'
        "model.logistics.fct_bool_chain",  // var and var == 'us'
        "model.logistics.fct_gate_report", // schema `config.enabled` jinja
        "model.logistics.sbx_probe",       // tree `+enabled` and/not/or
        "model.logistics.fct_sameas_gate", // var('alerts_enabled') is sameas true
        "model.logistics.fct_none_gate",   // var('none_probe', none) is none
    ] {
        assert!(m.contains(uid), "manifest mode drops {uid}");
        assert!(s.contains(uid), "source mode drops {uid}");
    }
    for uid in [
        "model.logistics.fct_env_gate",            // var('env') == 'prod'
        "model.logistics.fct_compliance_hold",     // var('region') in [...]
        "model.logistics.fct_flag_string",         // var('fleet_flag', false)
        "model.logistics.fct_defined_gate",        // nonexistent_flag is defined
        "source.logistics.carrier_feed.gps_pings", // `| as_bool` on a string var
    ] {
        assert!(!m.contains(uid), "manifest mode keeps {uid}");
        assert!(!s.contains(uid), "source mode keeps {uid}");
    }
}

#[test]
fn cli_vars_flip_enabled_identically_in_both_modes() {
    // The `--vars` manifest was generated by real dbt with `LOGISTICS_VARS`
    // on ITS `--vars`; the source load parses the same literal through
    // `CliVars`. CLI vars must reach every enabled scope identically:
    //   tree `+enabled`   experimental/* ON, sandbox OFF
    //   in-file config()  fct_env_gate ON (== 'prod'), fct_flag_string ON,
    //                     fct_lane_pairs ON (CLI beats the project-scoped
    //                     file value), fct_bool_chain/fct_service_alerts
    //                     OFF (alerts_enabled: false)
    //   schema `enabled`  fct_gate_report OFF, gps_pings ON ("True"|as_bool)
    //   test `enabled`    strict_event_check ON (the region_gate unique
    //                     test joins the multiset on both sides)
    let (m, s) = cmp::dags_with_vars(
        VARS_MANIFEST,
        PROJECT,
        VARS,
        "cargo xtask gen-fixture-manifest --project tests/fixtures/logistics_project \
         --vars '<common::LOGISTICS_VARS literal>' \
         --out tests/fixtures/logistics_vars_manifest.json",
    );
    cmp::assert_node_infos_identical(&m, &s, cmp::NO_DROPPED_EDGES, SOURCE_ONLY_EDGES);
    cmp::assert_closures_identical(&m, &s, cmp::NO_DROPPED_EDGES, SOURCE_ONLY_EDGES);
    cmp::assert_tests_identical(&m, &s);
    // The flips themselves, pinned — a silently-dropped vars map would
    // still compare equal and must NOT pass.
    for uid in [
        "model.logistics.exp_demand_forecast",
        "model.logistics.exp_empty_miles",
        "model.logistics.fct_env_gate",
        "model.logistics.fct_flag_string",
        "model.logistics.fct_lane_pairs",
        "model.logistics.fct_region_gate",
        "model.logistics.pilot_dock_queue",
        "model.logistics.pilot_lane_estimates",
        // `var('none_probe', none) is none` stays on — the map never sets it.
        "model.logistics.fct_none_gate",
        "source.logistics.carrier_feed.gps_pings",
    ] {
        assert!(m.contains(uid), "manifest+vars drops {uid}");
        assert!(s.contains(uid), "source+vars drops {uid}");
    }
    for uid in [
        "model.logistics.fct_bool_chain",
        "model.logistics.fct_gate_report",
        "model.logistics.fct_service_alerts",
        "model.logistics.sbx_probe",
        "model.logistics.fct_compliance_hold",
        "model.logistics.fct_returns",
        // alerts_enabled: false flips `is sameas true` off; the bare-name
        // `is defined` gate stays off under any map.
        "model.logistics.fct_sameas_gate",
        "model.logistics.fct_defined_gate",
        // `--vars` never touches vars the map doesn't name.
        "source.logistics.carrier_feed.retired_rates",
    ] {
        assert!(!m.contains(uid), "manifest+vars keeps {uid}");
        assert!(!s.contains(uid), "source+vars keeps {uid}");
    }
}

#[test]
fn source_config_enabled_drops_tables_in_both_modes() {
    // `config.enabled` is the ONLY `enabled` channel dbt honors for source
    // tables: `retired_rates` (table `config.enabled: false`) and
    // `legacy_rates` (source-level `config.enabled: false`) park under
    // `disabled`, while `revived_rates`' table-level `enabled: true`
    // re-enables it under the disabled source and `manual_overrides`'s
    // top-level `enabled: false` (a table property dbt ignores) stays in.
    let (m, s) = dags();
    for uid in [
        "source.logistics.carrier_feed.retired_rates",
        "source.logistics.archive.legacy_rates",
    ] {
        assert!(!m.contains(uid), "manifest mode keeps {uid}");
        assert!(!s.contains(uid), "source mode keeps {uid}");
    }
    for uid in [
        "source.logistics.archive.revived_rates",
        "source.logistics.carrier_feed.manual_overrides",
    ] {
        assert!(m.contains(uid), "manifest mode drops {uid}");
        assert!(s.contains(uid), "source mode drops {uid}");
    }
    // The disabled table's column test registers nothing either — dbt
    // warns that `unique` on retired_rates.rate_id depends on a disabled
    // source and leaves it unattached; source mode never synthesizes it.
    for (mode, dag) in [("manifest", &m), ("source", &s)] {
        assert!(
            dag.nodes().keys().all(|uid| !uid.contains("retired_rates")),
            "{mode} mode kept a node for the disabled table"
        );
    }
}

#[test]
fn hook_ref_is_an_edge_in_both_modes() {
    // `ref('ops_run_log')` inside `fct_shipments`' pre/post-hook SQL is a real
    // `depends_on` edge in the manifest — and the source loader's `ref()`
    // scan covers `config()` strings too, so source mode builds the same
    // edge. Pinned directly so a future change to either side is loud.
    let (m, s) = dags();
    let child = "model.logistics.fct_shipments";
    let parent = "model.logistics.ops_run_log";
    for (mode, dag) in [("manifest", &m), ("source", &s)] {
        assert!(
            dag.direct_parents(child).iter().any(|p| p == parent),
            "{mode} mode lost the hook-ref edge"
        );
    }
}

/// A Dag's macro records restricted to the comparable set — the root
/// project's `{% macro %}` definitions — as `uid -> macro_sql` pairs.
fn root_macro_defs(d: &Dag) -> BTreeMap<&str, Option<&str>> {
    d.macros()
        .iter()
        .filter(|(uid, _)| d.is_root_macro_def(uid))
        .map(|(uid, m)| (uid.as_str(), m.sql.as_deref()))
        .collect()
}

#[test]
fn root_project_macro_definitions_are_identical() {
    // The manifest's `macros` map reaches far wider than the project's
    // own table: `macro.dbt.*` internals, the vendored `shipkit`
    // package's defs, and `{% test %}` registrations — none of which a
    // source load can carry. The comparable slice is the six root
    // `{% macro %}` records; they must match uid-for-uid and
    // byte-for-byte across modes.
    let (m, s) = dags();
    let (md, sd) = (root_macro_defs(&m), root_macro_defs(&s));
    assert_eq!(
        md.len(),
        6,
        "the fixture's six project macros must sit inside the shared set: {md:?}"
    );
    assert_eq!(
        md, sd,
        "root `{{% macro %}}` definitions diverge between modes"
    );
}

#[test]
fn macro_body_deps_are_edges_in_both_modes() {
    // Every project-macro dependency shape must produce the same edge dbt
    // records in `depends_on.nodes` — the manifest numbers below come from
    // a real dbt 1.12.6 parse of this fixture. The resolved macro
    // unique_ids land in `depends_on.macros` identically too.
    let (m, s) = dags();
    let cases: &[(&str, &str)] = &[
        // `{{ ops_events_feed() }}` — literal `source()` in the body.
        (
            "model.logistics.stg_ops_events",
            "source.logistics.carrier_feed.ops_events",
        ),
        // `{{ carrier_feed('rate_cards') }}` — the call's argument binds
        // the body's `source('carrier_feed', table_name)`.
        (
            "model.logistics.stg_rate_cards",
            "source.logistics.carrier_feed.rate_cards",
        ),
        // `{{ feeder_chain('sensor_pings') }}` — the bound argument
        // forwards through a nested project-macro call.
        (
            "model.logistics.stg_sensor_pings",
            "source.logistics.carrier_feed.sensor_pings",
        ),
        // `{{ logistics.carrier_feed('dock_arrivals') }}` — a
        // project-qualified callee resolves to the same macro table.
        (
            "model.logistics.stg_dock_arrivals",
            "source.logistics.carrier_feed.dock_arrivals",
        ),
        // `{{ staging_model('stg_rate_cards') }}` — `ref()` under a bound
        // argument produces a model→model edge.
        (
            "model.logistics.int_rate_cards",
            "model.logistics.stg_rate_cards",
        ),
    ];
    for (mode, dag) in [("manifest", &m), ("source", &s)] {
        for (node, parent) in cases {
            assert!(
                dag.direct_parents(node).iter().any(|p| p == parent),
                "{mode} mode lost the macro-carried edge {parent} -> {node}"
            );
        }
    }
    // `depends_on.macros` records the direct invoke only — `stg_sensor_
    // pings` carries `feeder_chain`, while `carrier_feed` sits on
    // `macro.logistics.feeder_chain`'s own depends_on (the macro→macro
    // call graph), in both modes.
    for (mode, dag) in [("manifest", &m), ("source", &s)] {
        assert_eq!(
            dag.node_macros("model.logistics.stg_sensor_pings"),
            &["macro.logistics.feeder_chain"],
            "{mode} mode"
        );
        assert_eq!(
            dag.macros()
                .get("macro.logistics.feeder_chain")
                .map(|i| i.depends_on.as_slice()),
            Some(&["macro.logistics.carrier_feed".to_string()][..]),
            "{mode} mode"
        );
    }
}

#[test]
fn model_list_groups_are_identical() {
    // Left-pane grouping is edge-independent, so it compares exactly.
    let (m, s) = dags();
    let groups = |l: &dbtl::ModelList| -> Vec<(String, Vec<String>)> {
        l.groups
            .iter()
            .map(|g| {
                (
                    g.layer.clone(),
                    g.models.iter().map(|n| n.name.clone()).collect(),
                )
            })
            .collect()
    };
    assert_eq!(
        groups(&build_model_list(&m, SortMode::Layer)),
        groups(&build_model_list(&s, SortMode::Layer)),
        "left-pane grouping diverges"
    );
}

#[test]
fn lineage_renders_identical_outside_the_singular_badge_cone() {
    // Two render-visible divergences are expected: the `tests:N` badge on
    // `ops_run_log` (the manifest's singular test registers there; source
    // mode never synthesizes it), and the source-only branch edges — a
    // node's subgraph draws every parent/child it has, so the cone around
    // each `target.name`-omitted edge legitimately differs. A node's badge
    // shows in its own lineage and every ancestor/descendant's, so exactly
    // the nodes whose subgraph contains it are skipped — pinned below.
    let (m, s) = dags();
    let mut skip = cmp::affected_by_dropped_edges(&s, SOURCE_ONLY_EDGES);
    for uid in cmp::node_map(&m).keys() {
        if m.tests(uid).iter().any(|t| t.kind == "singular") {
            skip.insert(uid.clone());
            skip.extend(m.upstream(uid));
            skip.extend(m.downstream(uid));
        }
    }
    assert_eq!(
        skip,
        BTreeSet::from([
            "exposure.logistics.carrier_ops_dashboard".to_string(),
            "model.logistics.fct_delivery_scores".to_string(),
            "model.logistics.fct_py_delivery_risk".to_string(),
            "model.logistics.fct_shipments".to_string(),
            "model.logistics.ops_run_log".to_string(),
            "snapshot.logistics.shipment_status_snap".to_string(),
            // The unprovable branch edges' cones — every subgraph drawing
            // an edge only source mode records: the endpoints and their
            // shared seed ancestor (test nodes are side-map entries, not
            // graph nodes, so they never join the set).
            "model.logistics.int_order_split".to_string(),
            "model.logistics.stg_order_feed".to_string(),
            "model.logistics.stg_prod_orders".to_string(),
            "seed.logistics.orders".to_string(),
            "source.logistics.raw.prod_orders".to_string(),
        ]),
        "the render-divergent cone grew — re-check the fixture"
    );
    for uid in cmp::node_map(&m).keys() {
        if skip.contains(uid) {
            continue;
        }
        assert_eq!(
            layout(&m.subgraph(uid)).grid.to_text(),
            layout(&s.subgraph(uid)).grid.to_text(),
            "lineage render diverges for {uid}"
        );
    }
}

/// Per-rule finding counts for a dag, with the SQL resolver CLI lint uses.
fn rule_counts(dag: &Dag) -> BTreeMap<String, usize> {
    let cfg = LintConfig::default();
    let sql = SqlParseResolver::new(None, SqlDialect::from_dag(dag));
    let outcome = run_rules(LintInput::new(dag, &cfg).with_sql(Some(&sql)));
    let mut counts = BTreeMap::new();
    for f in &outcome.findings {
        *counts.entry(f.rule.name().to_string()).or_default() += 1;
    }
    counts
}

#[test]
fn lint_rule_counts_are_pinned_in_both_modes() {
    // Every rule's count is pinned absolutely per mode; the only
    // manifest↔source difference is the two SQL rules that legitimately see
    // only manifest-mode compiled SQL (the shipkit macro expansion):
    // `unused_cte` and `order_by_without_limit`. The source `config:` shapes
    // are inside the parity boundary too — the disabled tables (`retired_
    // rates`, `legacy_rates`) and their tests register nothing, while
    // `sources_without_freshness`/`unused_sources` see the same kept set.
    let (m, s) = dags();
    let expected = |pairs: &[(&str, usize)]| -> BTreeMap<String, usize> {
        pairs.iter().map(|(k, v)| (k.to_string(), *v)).collect()
    };
    // The four enabled-expression models declare columns without
    // per-column `description:` (+4 undocumented_columns), and
    // fct_region_gate's only unique test is var-gated — under the default
    // vars it counts as missing a primary-key pair (+1). The two kept
    // is-test gate models (fct_sameas_gate, fct_none_gate) land in
    // missing_primary_key_tests and undocumented_models each; the
    // python models fire the same language-agnostic rules a `.sql` file
    // would: fct_py_delivery_risk joins a source (direct_join_to_source +
    // marts_depend_on_source), stg_py_sensor_scores refs staging parents
    // (staging_depends_on_staging), carrier_feed.rate_cards picks up a
    // second consumer (source_fanout), and stg_py_sensor_scores itself is
    // the new leaf inside unused_models' unchanged 5 (it also gives
    // stg_rate_cards the downstream that was keeping it flagged).
    //
    // The latest additions shift the counts on purpose: the branch-split
    // `stg_order_feed`/`int_order_split` read a source and a staging model
    // through `target.name` arms — real dbt records only the `dev` arm, so
    // `raw.prod_orders`/`stg_prod_orders` have no recorded consumer —
    // and `stg_execute_feed`'s only dependency sits in `{% if execute %}`,
    // which parse never renders. The reads still don't flag: lint counts
    // them as possible, matching source mode's real edges (unused_sources
    // 5→6 covers `raw.unused_t` only; unused_models 4→7 adds the two leaf
    // reader models plus `stg_execute_feed`, itself a genuinely
    // unconsumed leaf in both modes). The earlier `loaded_at_field`-semantics source tables
    // sit unreferenced (unused_sources 3→5), lane_review's
    // `ref('stg_lane_updates')` gives that model a consumer
    // (unused_models 5→4), and the two exposures
    // fire the exposure rules — both depend on access-undeclared
    // (protected) models (exposures_dependent_on_private_models 2), and
    // lane_review's parent list mixes a staging view
    // (exposure_parents_materializations 1).
    assert_eq!(
        rule_counts(&m),
        expected(&[
            ("direct_join_to_source", 1),
            ("exposure_parents_materializations", 1),
            ("exposures_dependent_on_private_models", 2),
            ("marts_depend_on_source", 1),
            ("missing_primary_key_tests", 18),
            ("model_fanout", 1),
            ("order_by_without_limit", 1),
            ("root_models", 1),
            ("select_star", 1),
            ("source_fanout", 1),
            ("sources_without_freshness", 2),
            ("staging_depends_on_staging", 1),
            ("undocumented_columns", 12),
            ("undocumented_models", 16),
            ("unused_cte", 1),
            ("unused_models", 7),
            ("unused_sources", 6),
        ]),
        "manifest-mode rule counts drifted"
    );
    assert_eq!(
        rule_counts(&s),
        expected(&[
            ("direct_join_to_source", 1),
            ("exposure_parents_materializations", 1),
            ("exposures_dependent_on_private_models", 2),
            ("marts_depend_on_source", 1),
            ("missing_primary_key_tests", 18),
            ("model_fanout", 1),
            ("root_models", 1),
            ("select_star", 1),
            ("source_fanout", 1),
            ("sources_without_freshness", 2),
            ("staging_depends_on_staging", 1),
            ("undocumented_columns", 12),
            ("undocumented_models", 16),
            ("unused_models", 7),
            ("unused_sources", 6),
        ]),
        "source-mode rule counts drifted"
    );
}

#[test]
fn branch_only_consumers_count_as_uses_in_manifest_mode() {
    // The core guarantee, against the real-dbt manifest: the
    // `target.name == 'prod'` arms never rendered, so the manifest records
    // no consumer for `raw.prod_orders` or `stg_prod_orders` — yet neither
    // flags, because lint counts the literal branch calls as possible
    // reads. Source mode records the unprovable-arm calls as real edges
    // (a possible edge beats a missing one) and drops only the provably
    // dead ones, so both modes agree. `raw.unused_t` — nothing anywhere
    // reads it — still flags in both.
    let (m, s) = dags();
    // The manifest's depends_on stays dbt-faithful — the possible edges
    // never became real ones.
    assert_eq!(
        m.direct_parents("model.logistics.stg_order_feed"),
        &["source.logistics.raw.orders".to_string()],
        "manifest keeps only the rendered arm"
    );
    assert_eq!(
        m.direct_parents("model.logistics.int_order_split"),
        &["model.logistics.stg_orders".to_string()],
    );
    // The `{% if execute %}` arm is the sharpest omission: parse never
    // renders it (execute = false), so `depends_on` is EMPTY — and source
    // mode now matches, since a provably-dead arm's calls edge nowhere
    // either (the literal call still counts as a possible read for lint,
    // exactly as manifest mode).
    assert!(
        m.direct_parents("model.logistics.stg_execute_feed")
            .is_empty(),
        "the execute-only dependency leaves depends_on empty"
    );
    assert!(
        s.direct_parents("model.logistics.stg_execute_feed")
            .is_empty(),
        "source mode matches dbt: the execute arm edges nowhere"
    );
    assert!(
        m.raw_code("model.logistics.stg_execute_feed")
            .is_some_and(|sql| sql.contains("execute_feed")),
        "the literal call is still in raw_code"
    );
    assert!(
        m.compiled_code("model.logistics.stg_execute_feed")
            .is_some_and(|sql| sql.contains("execute_feed")),
        "dbt compile resolved the execute arm into compiled_code"
    );
    assert!(
        s.direct_parents("model.logistics.stg_order_feed")
            .iter()
            .any(|p| p == "source.logistics.raw.prod_orders"),
        "source mode records both arms"
    );
    let findings = |dag: &Dag, rule: dbtl::LintRule| -> Vec<String> {
        let cfg = LintConfig::default();
        run_rules(LintInput::new(dag, &cfg))
            .findings
            .iter()
            .filter(|f| f.rule == rule)
            .map(|f| f.node_uid.clone())
            .collect()
    };
    for (mode, dag) in [("manifest", &m), ("source", &s)] {
        let unused_sources = findings(dag, dbtl::LintRule::UnusedSources);
        assert!(
            !unused_sources.contains(&"source.logistics.raw.prod_orders".to_string()),
            "{mode} mode flags a branch-only source read"
        );
        assert!(
            !unused_sources.contains(&"source.logistics.raw.execute_feed".to_string()),
            "{mode} mode flags the execute-only source read"
        );
        assert!(
            unused_sources.contains(&"source.logistics.raw.unused_t".to_string()),
            "{mode} mode lost the truly-unused source"
        );
        let unused_models = findings(dag, dbtl::LintRule::UnusedModels);
        assert!(
            !unused_models.contains(&"model.logistics.stg_prod_orders".to_string()),
            "{mode} mode flags a branch-only ref target"
        );
    }
}

#[test]
fn compiled_only_lints_point_at_the_macro_call_site() {
    // Both compiled-only findings land on fct_audited_shipments — the model
    // whose entire body is the shipkit macro call — proving they come from
    // `compiled_code`, not the raw macro call.
    let (m, _s) = dags();
    let cfg = LintConfig::default();
    let sql = SqlParseResolver::new(None, SqlDialect::from_dag(&m));
    let mf = run_rules(LintInput::new(&m, &cfg).with_sql(Some(&sql))).findings;
    let audited: BTreeSet<&str> = mf
        .iter()
        .filter(|f| f.node_uid == "model.logistics.fct_audited_shipments")
        .map(|f| f.rule.name())
        .collect();
    for rule in ["unused_cte", "order_by_without_limit"] {
        assert!(
            audited.contains(rule),
            "{rule} did not fire on fct_audited_shipments in manifest mode"
        );
    }
}

#[test]
fn package_nodes_are_hidden_by_default() {
    // Under the default root-project scope the vendored package contributes
    // macros and tests but no nodes: `model.shipkit.shipkit_audit_trail`
    // must be absent — matching source mode, which never sees packages.
    let (m, _s) = dags();
    assert!(
        !m.contains("model.shipkit.shipkit_audit_trail"),
        "package node leaked into root scope"
    );
}

#[test]
fn package_nodes_appear_with_include_packages() {
    // `PackageScope::All` (the `--include-packages` flag) widens the graph to
    // the installed package: the shipkit model appears with its edges into
    // the root project's staging models.
    let full = load_dag(MANIFEST).expect("fixture manifest loads");
    let (all, _warnings) = PackageScope::All.apply_with_warnings(full);
    assert!(
        all.contains("model.shipkit.shipkit_audit_trail"),
        "--include-packages dropped the package model"
    );
    assert_eq!(
        all.direct_parents("model.shipkit.shipkit_audit_trail")
            .to_vec(),
        vec![
            "model.logistics.stg_shipment_events".to_string(),
            "model.logistics.stg_shipments".to_string(),
        ],
        "package model parents diverge"
    );
}

#[test]
fn package_nodes_provide_context_but_are_never_flagged() {
    // Under All scope the package model joins the graph for dependency
    // context, but lint in-scope stays root-only: no finding may point at a
    // shipkit node — and widening scope must not shift root findings.
    let full = load_dag(MANIFEST).expect("fixture manifest loads");
    let (all, _warnings) = PackageScope::All.apply_with_warnings(full);
    let all_counts = rule_counts(&all);
    let cfg = LintConfig::default();
    let sql = SqlParseResolver::new(None, SqlDialect::from_dag(&all));
    let outcome = run_rules(LintInput::new(&all, &cfg).with_sql(Some(&sql)));
    for f in &outcome.findings {
        assert!(
            !f.node_uid.starts_with("model.shipkit."),
            "package node {} was flagged by {}",
            f.node_uid,
            f.rule.name()
        );
    }
    let (m, _s) = dags();
    assert_eq!(
        all_counts,
        rule_counts(&m),
        "package scope shifted findings"
    );
}

#[test]
fn singular_test_registers_on_its_dependency_in_manifest() {
    // The shared exclusion, pinned directly: the manifest carries
    // `assert_run_log_model_name` on the node its SQL refs; source mode has
    // no singular tests at all.
    let (m, s) = dags();
    let uid = "model.logistics.ops_run_log";
    let kinds: Vec<&str> = m.tests(uid).iter().map(|t| t.kind.as_str()).collect();
    assert!(
        kinds.contains(&"singular"),
        "manifest mode lost the singular test on {uid}"
    );
    assert!(
        !s.tests(uid).iter().any(|t| t.kind == "singular"),
        "source mode synthesized a singular test on {uid}"
    );
}

#[test]
fn analyses_and_disabled_tests_never_enter_the_graph() {
    // analyses are recorded in the manifest (`analysis.*` nodes) but are not
    // lineage resources — same for the var-disabled singular test: neither
    // side exposes them.
    let (m, s) = dags();
    for uid in [
        "analysis.logistics.weekly_lane_review",
        "test.logistics.assert_events_in_order",
    ] {
        assert!(!m.contains(uid), "manifest mode keeps {uid}");
        assert!(!s.contains(uid), "source mode keeps {uid}");
    }
}
